import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.C-si7TFR.js";const g=JSON.parse('{"title":"Compose sub-agents","description":"","frontmatter":{"title":"Compose sub-agents"},"headers":[],"relativePath":"guide/sub-agents.md","filePath":"guide/sub-agents.md"}'),i={name:"guide/sub-agents.md"};function s(r,e,l,d,u,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="compose-sub-agents" tabindex="-1">Compose sub-agents <a class="header-anchor" href="#compose-sub-agents" aria-label="Permalink to &quot;Compose sub-agents&quot;">​</a></h1><p>A sub-agent delegates a bounded task to another agent configuration. It does not provide unlimited nesting and is not a sub-workflow.</p><h2 id="create-a-built-in-agent" tabindex="-1">Create a built-in agent <a class="header-anchor" href="#create-a-built-in-agent" aria-label="Permalink to &quot;Create a built-in agent&quot;">​</a></h2><ol><li>Open the parent agent card&#39;s action menu and add a built-in agent.</li><li>Open its configuration in the parent card&#39;s built-in section.</li><li>Define its task boundary and select only the tools it needs.</li><li>In the parent agent&#39;s sub-agent section, select this built-in agent.</li><li>Save, send the parent a small verifiable task and inspect the sub-agent call in the trace.</li></ol><p>The current entry exposes direct sub-agent selection on a parent. It does not promise arbitrary nesting or recursion. Prefer <a href="./workflows.html">workflows</a> or the <a href="./../sub_workflow.html">sub-workflow node</a> for strict ordering and failure branches.</p><h2 id="boundaries" tabindex="-1">Boundaries <a class="header-anchor" href="#boundaries" aria-label="Permalink to &quot;Boundaries&quot;">​</a></h2><ul><li>Built-in agents belong to their parent card; do not duplicate them as standalone agents.</li><li>Parent delegation, child instructions and tool permissions jointly affect the result.</li><li>Check references before deleting or changing an agent used by others.</li><li>Before upgrading a built-in agent to standalone, confirm the intended ownership and migration behavior.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p>If no sub-agent is called, check parent selection, model behavior and task wording. If a call fails, inspect the child&#39;s tools, model and permissions instead of simply adding loops or retries.</p>',9)])])}const b=t(i,[["render",s]]);export{g as __pageData,b as default};
